69	pub fn resolve_editorconfig_path(cwd: &Path) -> Option<PathBuf> {
70	    // Search the nearest `.editorconfig` from cwd upwards
71	    cwd.ancestors().map(|dir| dir.join(".editorconfig")).find(|p| p.exists())
72	}
