103	/// Resolved options for each file type.
104	/// Each variant contains only the options needed for that formatter.
105	#[derive(Debug)]
106	pub enum ResolvedOptions {
107	    /// For JS/TS files formatted by oxc_formatter.
108	    OxcFormatter {
109	        format_options: Box<FormatOptions>,
110	        /// For embedded language (xxx-in-js) formatting
111	        external_options: Value,
112	        /// Optional filepath override for external callbacks (e.g., Tailwind sorter).
113	        /// When set, this path is used instead of `FormatFileStrategy::path`
114	        /// as the `options.filepath` passed to external callbacks.
115	        /// Needed for js-in-xxx where the strategy path is a dummy,
116	        /// but callbacks need the parent file path to resolve their config.
117	        filepath_override: Option<PathBuf>,
118	        insert_final_newline: bool,
119	    },
120	    /// For TOML files.
121	    OxfmtToml { toml_options: TomlFormatterOptions, insert_final_newline: bool },
122	    /// For non-JS files formatted by external formatter (Prettier).
123	    #[cfg(feature = "napi")]
124	    ExternalFormatter { external_options: Value, insert_final_newline: bool },
125	    /// For `package.json` files: optionally sorted then formatted.
126	    #[cfg(feature = "napi")]
127	    ExternalFormatterPackageJson {
128	        external_options: Value,
129	        sort_package_json: Option<sort_package_json::SortOptions>,
130	        insert_final_newline: bool,
131	    },
132	}
