134	impl ResolvedOptions {
135	    /// Build `ResolvedOptions` from `OxfmtOptions`, `external_options`, and `FormatFileStrategy`.
136	    ///
137	    /// This also applies plugin-specific options (Tailwind, oxfmt plugin flags) based on strategy.
138	    fn from_oxfmt_options(
139	        oxfmt_options: OxfmtOptions,
140	        mut external_options: Value,
141	        strategy: &FormatFileStrategy,
142	    ) -> Self {
143	        // Apply plugin-specific options based on strategy
144	        finalize_external_options(&mut external_options, strategy);
145	
146	        #[cfg(feature = "napi")]
147	        let OxfmtOptions { format_options, toml_options, sort_package_json, insert_final_newline } =
148	            oxfmt_options;
149	        #[cfg(not(feature = "napi"))]
150	        let OxfmtOptions { format_options, toml_options, insert_final_newline, .. } = oxfmt_options;
151	
152	        match strategy {
153	            FormatFileStrategy::OxcFormatter { .. } => ResolvedOptions::OxcFormatter {
154	                format_options: Box::new(format_options),
155	                external_options,
156	                filepath_override: None,
157	                insert_final_newline,
158	            },
159	            FormatFileStrategy::OxfmtToml { .. } => {
160	                ResolvedOptions::OxfmtToml { toml_options, insert_final_newline }
161	            }
162	            #[cfg(feature = "napi")]
163	            FormatFileStrategy::ExternalFormatter { .. } => {
164	                ResolvedOptions::ExternalFormatter { external_options, insert_final_newline }
165	            }
166	            #[cfg(feature = "napi")]
167	            FormatFileStrategy::ExternalFormatterPackageJson { .. } => {
168	                ResolvedOptions::ExternalFormatterPackageJson {
169	                    external_options,
170	                    sort_package_json,
171	                    insert_final_newline,
172	                }
173	            }
174	            #[cfg(not(feature = "napi"))]
175	            _ => {
176	                unreachable!("If `napi` feature is disabled, this should not be passed here")
177	            }
178	        }
179	    }
180	}
