23	impl FormatService {
24	    pub fn new<T>(cwd: T, format_mode: OutputMode, formatter: SourceFormatter) -> Self
25	    where
26	        T: Into<Box<Path>>,
27	    {
28	        Self { cwd: cwd.into(), format_mode, formatter }
29	    }
30	
31	    /// Process entries as they are received from the channel
32	    pub fn run_streaming(
33	        &self,
34	        rx_entry: mpsc::Receiver<FormatEntry>,
35	        tx_error: &DiagnosticSender,
36	        tx_success: &mpsc::Sender<SuccessResult>,
37	    ) {
38	        rx_entry.into_iter().par_bridge().for_each(|entry| {
39	            let start_time = matches!(self.format_mode, OutputMode::Check).then(Instant::now);
40	
41	            let FormatEntry { strategy, config_resolver } = entry;
42	            let path = strategy.path();
43	            let Ok(source_text) = utils::read_to_string(path) else {
44	                // This happens if binary file is attempted to be formatted
45	                // e.g. `.ts` for MPEG-TS video file
46	                let diagnostics = DiagnosticService::wrap_diagnostics(
47	                    self.cwd.clone(),
48	                    path,
49	                    "",
50	                    vec![
51	                        oxc_diagnostics::OxcDiagnostic::error(format!(
52	                            "Failed to read file: {}",
53	                            path.display()
54	                        ))
55	                        .with_help("This may be due to the file being a binary or inaccessible."),
56	                    ],
57	                );
58	                let _ = tx_error.send(diagnostics);
59	                return;
60	            };
61	
62	            // Resolve options for this specific file using its scope's config
63	            let resolved_options = config_resolver.resolve(&strategy);
64	
65	            let (code, is_changed) =
66	                match self.formatter.format(&strategy, &source_text, resolved_options) {
67	                    FormatResult::Success { code, is_changed } => (code, is_changed),
68	                    FormatResult::Error(diagnostics) => {
69	                        let errors = DiagnosticService::wrap_diagnostics(
70	                            self.cwd.clone(),
71	                            path,
72	                            &source_text,
73	                            diagnostics,
74	                        );
75	                        let _ = tx_error.send(errors);
76	                        return;
77	                    }
78	                };
79	
80	            // Write back if needed
81	            if matches!(self.format_mode, OutputMode::Write) && is_changed {
82	                match fs::write(path, &code) {
83	                    Ok(()) => (),
84	                    Err(err) => {
85	                        let diagnostics = DiagnosticService::wrap_diagnostics(
86	                            self.cwd.clone(),
87	                            path,
88	                            "",
89	                            vec![oxc_diagnostics::OxcDiagnostic::error(format!(
90	                                "Failed to save '{}': {err}",
91	                                path.display()
92	                            ))],
93	                        );
94	                        let _ = tx_error.send(diagnostics);
95	                        return;
96	                    }
97	                }
98	            }
99	
100	            // Report result
101	            let result = match (&self.format_mode, is_changed) {
102	                (OutputMode::Check | OutputMode::ListDifferent, true) => {
103	                    let display_path = path
104	                        // Show path relative to `cwd` for cleaner output
105	                        .strip_prefix(&self.cwd)
106	                        .unwrap_or(path)
107	                        .to_string_lossy()
